import {observable, action, computed} from "mobx";
import {serializable, map, primitive, serialize} from "serializr";
import {
    ModuleAccess, SpecialAccess, allModulesAcceessUser, allSpecialAccessUser,
    allResponsibleRoles
} from "../Constants";
import UserModuleStore from "../UserModuleStore";

// Интерфейс для данных получаемых от сервера в качестве json
export interface UserData {
    ID?:string;
    Name?:string;
    Login?:string;
    Password?:string;
    Email?:string;
    InnerPhone?:string;
    BirthDay?:string;
    BirthMonth?:string;
    Position?:string;
    BranchOfficeID?:string;
    GroupID?:string;
    Active?:'0'|'1';
    ResponsibleRoles?: {[key: string]: boolean};
    moduleAccess?: ModuleAccess;
    specialAccess?: ModuleAccess;
    Idle?:string;
    IdleTimestamp?:number;
}

export class User {

    @observable @serializable ID: string;
    @observable @serializable Name: string;
    @observable @serializable Login: string;
    @observable @serializable Password: string;
    @observable @serializable Email: string;
    @observable @serializable InnerPhone: string;
    @observable @serializable BirthDay: string;
    @observable @serializable BirthMonth: string;
    @observable @serializable Position: string;
    @observable @serializable BranchOfficeID: string;
    @observable @serializable GroupID: string;
    @observable @serializable Active: '0'|'1';
    @observable @serializable(map(primitive())) ResponsibleRoles: {[key: string]: boolean};

    @observable @serializable(map(primitive())) moduleAccess: ModuleAccess;
    @observable @serializable(map(primitive())) specialAccess: SpecialAccess;

    @observable Idle: string;
    @observable IdleTimestamp: number;

    @observable isSaving: boolean;

    store: UserModuleStore;

    [key: string]: any;

    constructor(userData: UserData, store: UserModuleStore) {

        this.fillData(userData);
        this.store = store;

    }

    @computed get group() {
        return this.store.findGroupById(this.GroupID);
    }

    fillData(userData: UserData) {

        this.ID = userData.ID || '';
        this.Name = userData.Name || '';
        this.Login = userData.Login || '';
        this.Password = userData.Password || '';
        this.Email = userData.Email || '';
        this.InnerPhone = userData.InnerPhone || '';
        this.BirthDay = userData.BirthDay || '';
        this.BirthMonth = userData.BirthMonth || '';
        this.Position = userData.Position || '';
        this.BranchOfficeID = userData.BranchOfficeID || '';
        this.GroupID = userData.GroupID || '';

        this.Active = userData.Active || '1';
        this.ResponsibleRoles = {...allResponsibleRoles, ...(userData.ResponsibleRoles || {})};
        this.moduleAccess = {...allModulesAcceessUser, ...(userData.moduleAccess || {})};
        this.specialAccess = {...allSpecialAccessUser, ...(userData.specialAccess || {})};

        this.Idle = userData.Idle || '';
        this.IdleTimestamp = userData.IdleTimestamp || 0;
    }

    @action toggleResponsibleRole(roleKey: string) {
        this.ResponsibleRoles[roleKey] = !this.ResponsibleRoles[roleKey];
    }

    @action onChange(fieldKey: string, value: string) {
        this[fieldKey] = value;
    }

    @action onChangeModuleAccess(moduleKey: string, newAccess: number) {
        this.moduleAccess[moduleKey] = newAccess;
    }

    @action onChangeSpecialAccess(accessKey: string, newAccess: number) {
        this.specialAccess[accessKey] = newAccess;
    }

    @action changeAccessAll(newAccess: number) {

        for (let moduleKey in this.moduleAccess) {
            this.moduleAccess[moduleKey] = newAccess;
        }

        // В списке specialAccess возможны всего три варианта: Inherit (-1), No (0), Yes (1)
        // Вариант 2 (Write) отсутвует, поэтому нужно предваритено проверить
        if (newAccess === 2) {
            newAccess = 1;
        }
        for (let accessKey in this.specialAccess) {
            this.specialAccess[accessKey] = newAccess;
        }

    }

    validate() {

        let isValid = true;

        if (this.Name.trim() === '') {
            Light.toastError('Empty Name');
            isValid = false;
        }

        if (this.Login.trim() === '') {
            Light.toastError('Empty Login');
            isValid = false;
        }

        if (this.Active === '1' && this.Password.trim() === '') {
            Light.toastError('Empty Password');
            isValid = false;
        }

        if (this.GroupID === '') {
            Light.toastError('Group not selected');
            isValid = false;
        }

        return isValid;
    }

    @action save = () => {

        if (this.isSaving) {
            return;
        }

        if (!this.validate()) {
            return;
        }

        // Установим специальный флаг на этом шипменте, чтобы заблокировать кнопку Save
        // Флаг специально находится внутри класса User
        // если пользователь перейдёт к другой записе пока данный пользователь сохраняется, кнопка Save разблокируется (так и должно быть)!
        this.isSaving = true;

        const postData = serialize(this);

        $.post('?a=UserModule&p=Submit', postData)
            .done(action((newUserData: any) => {
                if (this.ID === '') {
                    // Этот пользователь был только что добавлен в базу (новый пользователь)
                    // Нужно добавить его и в массив в store
                    this.store.users.push(this);
                }
                this.fillData(newUserData);
                this.isSaving = false;
                Light.toastSuccess('User ' + newUserData.Name + ' saved');
            }))
            .fail(action(() => {
                this.isSaving = false;
                Light.toastError('Save failed');
            }));

    };

}


